<?= $this->extend('layouts/admin_master') ?><?= $this->section('content') ?><div class="d-flex justify-content-between mb-4"><div><h1 class="h4 mb-1">Growth & CRM</h1><p class="text-muted mb-0">Promotion, referral và review có kiểm duyệt.</p></div></div><div class="row g-4"><div class="col-xl-4"><div class="card shadow-sm"><div class="card-header">Tạo promotion</div><div class="card-body"><form method="post" action="<?= base_url('admin/growth/promotions/store') ?>"><?= csrf_field() ?><input name="name" class="form-control mb-2" placeholder="Tên chương trình" required><input name="code" class="form-control mb-2" placeholder="Mã PBWELCOME" required><div class="row g-2 mb-2"><div class="col-6"><select name="discount_type" class="form-select"><option value="percent">%</option><option value="fixed">Số tiền</option></select></div><div class="col-6"><input type="number" step="0.01" min="0.01" name="discount_value" class="form-control" placeholder="Giá trị" required></div></div><div class="row g-2 mb-2"><div class="col-6"><input type="number" step="0.01" min="0" name="min_order_amount" class="form-control" placeholder="Đơn tối thiểu"></div><div class="col-6"><input type="number" step="0.01" min="0" name="max_discount" class="form-control" placeholder="Giảm tối đa"></div></div><div class="row g-2"><div class="col-6"><input type="datetime-local" name="starts_at" class="form-control" required></div><div class="col-6"><input type="datetime-local" name="ends_at" class="form-control" required></div></div><button class="btn btn-primary w-100 mt-3">Tạo promotion</button></form></div></div></div><div class="col-xl-8"><div class="card shadow-sm mb-4"><div class="card-header">Promotion đang có</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Mã</th><th>Giảm</th><th>Thời gian</th><th>Trạng thái</th></tr></thead><tbody><?php foreach($promotions as $promotion): ?><tr><td><strong><?= esc($promotion->code) ?></strong><div class="small text-muted"><?= esc($promotion->name) ?></div></td><td><?= $promotion->discount_type==='percent'?(float)$promotion->discount_value.'%':number_format((float)$promotion->discount_value,0,',','.') . ' đ' ?></td><td><?= esc($promotion->starts_at) ?> → <?= esc($promotion->ends_at) ?></td><td><?= esc($promotion->status) ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="card shadow-sm mb-4"><div class="card-header">Referral</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Người giới thiệu</th><th>Người mới</th><th>Thưởng</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($referrals as $ref): ?><tr><td><?= esc($ref->referrer_name) ?></td><td><?= esc($ref->referred_name) ?></td><td><?= number_format((float)$ref->reward_amount,0,',','.') ?> đ</td><td><?= esc($ref->status) ?></td><td><?php if($ref->status==='pending'): ?><form method="post" action="<?= base_url('admin/growth/referrals/qualify/'.$ref->id) ?>" class="d-inline"><?= csrf_field() ?><button class="btn btn-sm btn-outline-primary">Qualify</button></form><?php elseif($ref->status==='qualified'): ?><form method="post" action="<?= base_url('admin/growth/referrals/reward/'.$ref->id) ?>" class="d-inline"><?= csrf_field() ?><button class="btn btn-sm btn-outline-success">Trả thưởng</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="card shadow-sm"><div class="card-header">Review chờ duyệt</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Player</th><th>Đối tượng</th><th>Rating</th><th>Nội dung</th><th></th></tr></thead><tbody><?php foreach($reviews as $review): ?><tr><td><?= esc($review->player_name) ?></td><td><?= esc($review->entity_type) ?> #<?= (int)$review->entity_id ?></td><td><?= (int)$review->rating ?>/5</td><td><?= esc($review->body) ?></td><td><?php if($review->status==='pending'): ?><form method="post" action="<?= base_url('admin/growth/reviews/'.$review->id.'/status') ?>" class="d-flex gap-1"><?= csrf_field() ?><input type="hidden" name="status" value="published"><button class="btn btn-sm btn-success">Duyệt</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div><?= $this->endSection() ?>
